//! Selection of the kept keys and rendering of `keymap/generated.rs`.

use std::collections::BTreeMap;
use std::fmt::Write as _;

use anyhow::{Result, bail, ensure};

use crate::parse::DomCode;

/// `win` value meaning "no Windows scan code".
const WIN_NONE: u16 = 0;
/// `mac` value meaning "no macOS key code".
const MAC_NONE: u16 = 0xFFFF;
/// Length of `MAC_TO_HID` (macOS virtual key codes are 7-bit).
const MAC_TABLE_LEN: usize = 128;
/// Length of `WIN_TO_HID`: 256 plain plus 256 extended scan codes.
const WIN_TABLE_LEN: usize = 512;

const HEADER: &str = "\
// @generated by tools/keymap-gen from tools/keymap-gen/data/dom_code_data.inc. DO NOT EDIT.
// Derived from Chromium ui/events/keycodes/dom/dom_code_data.inc, Copyright 2013 The Chromium Authors, BSD-3-Clause; see THIRD_PARTY_NOTICES
";

/// One kept key.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Key {
    pub hid: u32,
    pub win: u16,
    pub mac: u16,
    /// Empty if Chromium has no DOM `code` string for the key.
    pub code: String,
}

/// Keeps keyboard-page (0x07, usage >= 0x04) and consumer-page (0x0C)
/// entries that have at least one native code, sorted by HID usage. Fails on
/// a duplicate HID usage, Windows scan code or macOS key code, and on native
/// codes that do not fit the lookup tables.
pub fn select(entries: &[DomCode]) -> Result<Vec<Key>> {
    let mut kept: Vec<&DomCode> = entries.iter().filter(|e| is_kept(e)).collect();
    kept.sort_by_key(|e| e.usb);
    check_unique(&kept, "HID usage", |e| Some(e.usb))?;
    check_unique(&kept, "Windows scan code", |e| {
        (e.win != WIN_NONE).then_some(u32::from(e.win))
    })?;
    check_unique(&kept, "macOS key code", |e| {
        (e.mac != MAC_NONE).then_some(u32::from(e.mac))
    })?;
    for e in &kept {
        ensure!(
            e.mac == MAC_NONE || usize::from(e.mac) < MAC_TABLE_LEN,
            "line {}: {}: macOS key code {:#06x} is outside 0x00..=0x7f",
            e.line,
            e.id,
            e.mac
        );
        ensure!(
            matches!(e.win >> 8, 0x00 | 0xE0),
            "line {}: {}: Windows scan code {:#06x} is neither 0x00xx nor 0xe0xx",
            e.line,
            e.id,
            e.win
        );
    }
    Ok(kept
        .into_iter()
        .map(|e| Key {
            hid: e.usb,
            win: e.win,
            mac: e.mac,
            code: e.code.clone().unwrap_or_default(),
        })
        .collect())
}

fn is_kept(e: &DomCode) -> bool {
    let page = e.usb >> 16;
    let usage = e.usb & 0xFFFF;
    let wanted_page = (page == 0x07 && usage >= 0x04) || page == 0x0C;
    wanted_page && (e.win != WIN_NONE || e.mac != MAC_NONE)
}

fn check_unique(
    kept: &[&DomCode],
    what: &str,
    key: impl Fn(&DomCode) -> Option<u32>,
) -> Result<()> {
    let mut seen: BTreeMap<u32, &DomCode> = BTreeMap::new();
    for &e in kept {
        let Some(value) = key(e) else { continue };
        if let Some(first) = seen.insert(value, e) {
            bail!(
                "duplicate {what} {value:#x}: {} (line {}) and {} (line {})",
                first.id,
                first.line,
                e.id,
                e.line
            );
        }
    }
    Ok(())
}

/// Index of a Windows scan code in `WIN_TO_HID`: `(sc & 0xFF) | 0x100` if extended.
fn win_index(win: u16) -> usize {
    let extended = win >> 8 == 0xE0;
    usize::from(win & 0xFF) | if extended { 0x100 } else { 0 }
}

/// `0x07_0004` style literal (page, then usage); `0` for "none".
fn hid_literal(hid: u32) -> String {
    if hid == 0 {
        "0".to_owned()
    } else {
        format!("{:#04X}_{:04X}", hid >> 16, hid & 0xFFFF)
    }
}

/// Renders `generated.rs`. `keys` must come from [`select`]. Deterministic:
/// the output depends only on `keys`.
pub fn render(keys: &[Key]) -> String {
    let mut mac_to_hid = [None::<&Key>; MAC_TABLE_LEN];
    let mut win_to_hid = [None::<&Key>; WIN_TABLE_LEN];
    for key in keys {
        if key.mac != MAC_NONE {
            mac_to_hid[usize::from(key.mac)] = Some(key);
        }
        if key.win != WIN_NONE {
            win_to_hid[win_index(key.win)] = Some(key);
        }
    }

    let mut out = String::from(HEADER);
    out.push_str(
        "
/// One keyboard-page or consumer-page key and its native codes.
pub(crate) struct KeyEntry {
    /// HID usage: `(usage_page << 16) | usage`.
    pub hid: u32,
    /// Windows scan code as reported by `KBDLLHOOKSTRUCT`, `0xE0xx` if extended; 0 = none.
    pub win: u16,
    /// macOS virtual key code; `0xFFFF` = none.
    pub mac: u16,
    /// DOM `KeyboardEvent.code` value; empty if Chromium defines none.
    pub code: &'static str,
}
",
    );

    out.push_str("\n/// Every kept key, sorted by `hid` (unique).\n");
    let _ = writeln!(
        out,
        "pub(crate) static KEYS: [KeyEntry; {}] = [",
        keys.len()
    );
    for key in keys {
        let _ = writeln!(
            out,
            "    KeyEntry {{ hid: {}, win: {:#06X}, mac: {:#06X}, code: \"{}\" }},",
            hid_literal(key.hid),
            key.win,
            key.mac,
            key.code
        );
    }
    out.push_str("];\n");

    out.push_str("\n/// macOS virtual key code -> HID usage; 0 = none.\n");
    let _ = writeln!(
        out,
        "pub(crate) static MAC_TO_HID: [u32; {MAC_TABLE_LEN}] = ["
    );
    for (code, key) in mac_to_hid.iter().enumerate() {
        push_slot(&mut out, *key, &format!("{code:#04X}"));
    }
    out.push_str("];\n");

    out.push_str(
        "\n/// Windows scan code -> HID usage, indexed by `(sc & 0xFF) | 0x100` if extended; 0 = none.\n",
    );
    let _ = writeln!(
        out,
        "pub(crate) static WIN_TO_HID: [u32; {WIN_TABLE_LEN}] = ["
    );
    for (index, key) in win_to_hid.iter().enumerate() {
        let scan = if index & 0x100 != 0 {
            0xE000 | (index & 0xFF)
        } else {
            index
        };
        push_slot(&mut out, *key, &format!("{scan:#06X}"));
    }
    out.push_str("];\n");
    out
}

/// One lookup-table line: the HID literal, then the native code and key name.
fn push_slot(out: &mut String, key: Option<&Key>, native: &str) {
    let value = format!("{},", hid_literal(key.map_or(0, |k| k.hid)));
    match key {
        Some(key) if !key.code.is_empty() => {
            let _ = writeln!(out, "    {value:<10} // {native} {}", key.code);
        }
        _ => {
            let _ = writeln!(out, "    {value:<10} // {native}");
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::FIXTURE;
    use crate::parse::parse;

    fn fixture_keys() -> Vec<Key> {
        select(&parse(FIXTURE).unwrap()).unwrap()
    }

    fn entry(usb: u32, win: u16, mac: u16, id: &str) -> DomCode {
        DomCode {
            line: 1,
            usb,
            win,
            mac,
            code: Some(id.to_owned()),
            id: id.to_owned(),
        }
    }

    #[test]
    fn keeps_only_keyboard_and_consumer_keys_with_a_native_code() {
        let hids: Vec<u32> = fixture_keys().iter().map(|k| k.hid).collect();
        // Excluded: page 0x00 (NONE), page 0x01 (Sleep), usage < 4 (0x070001)
        // and Open (no native code).
        assert_eq!(
            hids,
            [0x07_0004, 0x07_0055, 0x07_00E3, 0x0C_00CD, 0x0C_00E2]
        );
    }

    #[test]
    fn null_code_becomes_empty_string() {
        let keys = fixture_keys();
        let mute = keys.iter().find(|k| k.hid == 0x0C_00E2).unwrap();
        assert_eq!(mute.code, "");
        assert!(
            render(&keys).contains(
                "    KeyEntry { hid: 0x0C_00E2, win: 0xE020, mac: 0xFFFF, code: \"\" },\n"
            )
        );
    }

    #[test]
    fn duplicates_are_errors() {
        let base = || {
            vec![
                entry(0x07_0004, 0x001E, 0x0000, "A"),
                entry(0x07_0005, 0x0030, 0x000B, "B"),
            ]
        };

        let mut dup_hid = base();
        dup_hid.push(entry(0x07_0004, 0x0031, 0x000C, "A2"));
        let err = select(&dup_hid).unwrap_err().to_string();
        assert!(err.contains("duplicate HID usage 0x70004"), "{err}");

        let mut dup_win = base();
        dup_win.push(entry(0x07_0006, 0x001E, 0x000C, "C"));
        let err = select(&dup_win).unwrap_err().to_string();
        assert!(err.contains("duplicate Windows scan code 0x1e: A"), "{err}");

        let mut dup_mac = base();
        dup_mac.push(entry(0x07_0006, 0x0031, 0x000B, "C"));
        let err = select(&dup_mac).unwrap_err().to_string();
        assert!(err.contains("duplicate macOS key code 0xb: B"), "{err}");

        // Sentinels and excluded entries never count as duplicates.
        let mut sentinels = base();
        sentinels.push(entry(0x07_0006, 0x0000, 0x000C, "C"));
        sentinels.push(entry(0x07_0007, 0x0031, 0xFFFF, "D"));
        sentinels.push(entry(0x07_0008, 0x0032, 0xFFFF, "E"));
        sentinels.push(entry(0x01_0082, 0x001E, 0x0000, "Excluded"));
        assert_eq!(select(&sentinels).unwrap().len(), 5);
    }

    #[test]
    fn native_codes_must_fit_the_tables() {
        let err = select(&[entry(0x07_0004, 0x001E, 0x0080, "A")])
            .unwrap_err()
            .to_string();
        assert!(err.contains("macOS key code 0x0080"), "{err}");
        let err = select(&[entry(0x07_0004, 0xE11D, 0x0000, "A")])
            .unwrap_err()
            .to_string();
        assert!(err.contains("Windows scan code 0xe11d"), "{err}");
    }

    #[test]
    fn render_is_deterministic_and_order_independent() {
        let entries = parse(FIXTURE).unwrap();
        let mut reversed = entries.clone();
        reversed.reverse();
        let first = render(&select(&entries).unwrap());
        assert_eq!(first, render(&select(&entries).unwrap()));
        assert_eq!(first, render(&select(&reversed).unwrap()));
    }

    #[test]
    fn render_layout() {
        let out = render(&fixture_keys());
        assert!(out.starts_with(HEADER));
        assert!(out.contains("pub(crate) static KEYS: [KeyEntry; 5] = [\n"));
        assert!(out.contains(
            "    KeyEntry { hid: 0x07_0004, win: 0x001E, mac: 0x0000, code: \"KeyA\" },\n"
        ));
        assert!(out.contains(
            "pub(crate) static MAC_TO_HID: [u32; 128] = [\n    0x07_0004, // 0x00 KeyA\n"
        ));
        assert!(out.contains("    0x07_00E3, // 0x37 MetaLeft\n"));
        assert!(out.contains("    0,         // 0x7F\n];\n"));
        assert!(
            out.contains(
                "pub(crate) static WIN_TO_HID: [u32; 512] = [\n    0,         // 0x0000\n"
            )
        );
        assert!(out.contains("    0x07_0055, // 0x0037 NumpadMultiply\n"));
        assert!(out.contains("    0x07_00E3, // 0xE05B MetaLeft\n"));
        assert!(out.contains("    0x0C_00E2, // 0xE020\n"));
        assert!(out.ends_with("    0,         // 0xE0FF\n];\n"));
        assert_eq!(out.matches("// 0x").count(), MAC_TABLE_LEN + WIN_TABLE_LEN);
    }
}
